+{
+    int acc = 0;
+    for (int i = 0; i < Iterations; i++)
+    {
+        acc = unchecked(acc + Reg<A1, B1, H1>.Done);
+    }
+    return acc;
+});
+
+// REG_READ_MIXED4_INLINE — same as MIXED4 but inline. Lower bound for
+// the multi-factory render-pass scenario.
